function computeLanguagePercentages(siteData, filter = 'all') {
  const counts = {};
  Object.keys(LANGUAGES_META).forEach(k => counts[k] = 0);

  const allWorks = Array.isArray(siteData.works) ? siteData.works : [];
  const filteredWorks = allWorks.filter(w => {
    if (filter === 'all') return true;
    const auth = (w.author || '').toLowerCase();
    if (filter === 'hardovere') return auth.includes('hardovere');
    if (filter === 'sodabarblga') return auth.includes('sodabarblga');
    return true;
  });

  let totalTags = 0;
  filteredWorks.forEach(w => {
    (w.langs || []).forEach(l => {
      if (counts[l] !== undefined) {
        counts[l] += 1;
        totalTags += 1;
      }
    });
  });

  let sourceMode = 'portfolio';
  if (totalTags === 0) {
    sourceMode = 'profile_fallback';
    if (filter === 'hardovere' || filter === 'all') {
      (siteData.profiles.hardovere.langs || []).forEach(l => {
        if (counts[l] !== undefined) { counts[l] += 1; totalTags += 1; }
      });
    }
    if (filter === 'sodabarblga' || filter === 'all') {
      (siteData.profiles.sodabarblga.langs || []).forEach(l => {
        if (counts[l] !== undefined) { counts[l] += 1; totalTags += 1; }
      });
    }
  }

  if (totalTags === 0) totalTags = 1;

  const items = Object.keys(LANGUAGES_META).map(k => {
    const rawPct = (counts[k] / totalTags) * 100;
    return {
      key: k,
      name: LANGUAGES_META[k].name,
      color: LANGUAGES_META[k].color,
      svg: LANGUAGES_META[k].svg,
      count: counts[k],
      pct: Number(rawPct.toFixed(1))
    };
  }).filter(item => item.count > 0 || filter === 'all');

  items.sort((a, b) => b.count - a.count);

  return {
    items,
    worksCount: filteredWorks.length,
    sourceMode
  };
}

function loadSiteData() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return JSON.parse(JSON.stringify(DEFAULT_DATA));
    const parsed = JSON.parse(raw);
    if (parsed.profiles && parsed.profiles.hardovere && !parsed.profiles.hardovere.avatarFallback) {
      parsed.profiles.hardovere.avatarFallback = DEFAULT_DATA.profiles.hardovere.avatarFallback;
    }
    if (parsed.profiles && parsed.profiles.sodabarblga && !parsed.profiles.sodabarblga.avatarFallback) {
      parsed.profiles.sodabarblga.avatarFallback = DEFAULT_DATA.profiles.sodabarblga.avatarFallback;
    }
    return Object.assign(JSON.parse(JSON.stringify(DEFAULT_DATA)), parsed);
  } catch (e) {
    return JSON.parse(JSON.stringify(DEFAULT_DATA));
  }
}

function saveSiteData(data) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}
